, size 16 em cards e tiles)","tree":{"sha":"60f915674cfa5b1429e877b70e97a017648d197b","url":"https://api.github.com/repos/priscilla-morimitsu/delivery-app/git/trees/60f915674cfa5b1429e877b70e97a017648d197b"},"url":"https://api.github.com/repos/priscilla-morimitsu/delivery-app/git/commits/fb1759d6ef56120ab4fb28b89f7ac28a5a1cc936","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/81304954?v=4","events_url":"https://api.github.com/users/priscilla-morimitsu/events{/privacy}","followers_url":"https://api.github.com/users/priscilla-morimitsu/followers","following_url":"https://api.github.com/users/priscilla-morimitsu/following{/other_user}","gists_url":"https://api.github.com/users/priscilla-morimitsu/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/priscilla-morimitsu","id":81304954,"login":"priscilla-morimitsu","node_id":"MDQ6VXNlcjgxMzA0OTU0","organizations_url":"https://api.github.com/users/priscilla-morimitsu/orgs","received_events_url":"https://api.github.com/users/priscilla-morimitsu/received_events","repos_url":"https://api.github.com/users/priscilla-morimitsu/repos","site_admin":false,"starred_url":"https://api.github.com/users/priscilla-morimitsu/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/priscilla-morimitsu/subscriptions","type":"User","url":"https://api.github.com/users/priscilla-morimitsu","user_view_type":"public"},"html_url":"https://github.com/priscilla-morimitsu/delivery-app/commit/fb1759d6ef56120ab4fb28b89f7ac28a5a1cc936","node_id":"C_kwDOSl5QOdoAKGZiMTc1OWQ2ZWY1NjEyMGFiNGZiMjhiODlmN2FjMjhhNWExY2M5MzY","parents":[{"html_url":"https://github.com/priscilla-morimitsu/delivery-app/commit/c3c4c1714a8d89b28d0e3e3f9696a21078f4e7bc","sha":"c3c4c1714a8d89b28d0e3e3f9696a21078f4e7bc","url":"https://api.github.com/repos/priscilla-morimitsu/delivery-app/commits/c3c4c1714a8d89b28d0e3e3f9696a21078f4e7b