ackage configuration.","tree":{"sha":"b48c73fccadedba4014b146dee968850b2171156","url":"https://api.github.com/repos/byte-od/mermaid-diagram-driven-development/git/trees/b48c73fccadedba4014b146dee968850b2171156"},"url":"https://api.github.com/repos/byte-od/mermaid-diagram-driven-development/git/commits/588c3625e56391e1091f0be75f116e1b15817032","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/47756842?v=4","events_url":"https://api.github.com/users/byte-od/events{/privacy}","followers_url":"https://api.github.com/users/byte-od/followers","following_url":"https://api.github.com/users/byte-od/following{/other_user}","gists_url":"https://api.github.com/users/byte-od/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/byte-od","id":47756842,"login":"byte-od","node_id":"MDQ6VXNlcjQ3NzU2ODQy","organizations_url":"https://api.github.com/users/byte-od/orgs","received_events_url":"https://api.github.com/users/byte-od/received_events","repos_url":"https://api.github.com/users/byte-od/repos","site_admin":false,"starred_url":"https://api.github.com/users/byte-od/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/byte-od/subscriptions","type":"User","url":"https://api.github.com/users/byte-od","user_view_type":"public"},"html_url":"https://github.com/byte-od/mermaid-diagram-driven-development/commit/588c3625e56391e1091f0be75f116e1b15817032","node_id":"C_kwDOSl5mtdoAKDU4OGMzNjI1ZTU2MzkxZTEwOTFmMGJlNzVmMTE2ZTFiMTU4MTcwMzI","parents":[{"html_url":"https://github.com/byte-od/mermaid-diagram-driven-development/commit/859857af0f1d794fe09b37e0377b6c654d1e2a0f","sha":"859857af0f1d794fe09b37e0377b6c654d1e2a0f","url":"https://api.github.com/repos/byte-od/mermaid-diagram-driven-development/commits/859857af0f1d794fe09b37e0377b6c654d1e2a0f"}],"sha":"588c3625e56391e1091f0be75f116e1b15817032","url":"https://api.github.com/repos/byte-od/me