INSERT INTO collection_pages VALUES('ea572497b762df151c0290d6ca3b7c4d08044f893f733a787b3b04327a1dadfd','e653cf50aab86aa1f8781a0e191bbff502b47e27e0d245bb3fb1ee73d9299c99','{"hasNext":false,"items":[{"author":{"account":null,"email":"mhosseinmalek@tract.eco","name":"Mohammad Hossein Malek"},"authoredDate":"2026-05-24T17:06:02Z","committedDate":"2026-05-24T17:06:02Z","committer":{"account":null,"email":"mhosseinmalek@tract.eco","name":"Mohammad Hossein Malek"},"observedAt":"2026-10-08T23:09:52.232Z","repositoryId":1248457338,"sha":"4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f"}],"observedAt":"2026-10-08T23:09:52.232Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/MHMALEK/multi-stack-showcase/commits/4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f/comments","commit":{"author":{"date":"2026-05-24T17:06:02Z","email":"mhosseinmalek@tract.eco","name":"Mohammad Hossein Malek"},"comment_count":0,"committer":{"date":"2026-05-24T17:06:02Z","email":"mhosseinmalek@tract.eco","name":"Mohammad Hossein Malek"},"message":"feat: initial release\n\nPolyglot dev-environment showcase: three backend services in three\nlanguages, two shared data stores, a static frontend with nginx fan-out,\nand a Cobra-based host CLI that wraps docker compose through composego.\n\nServices:\n- api-py     FastAPI + asyncpg + postgres (/users)\n- api-node   Express + redis              (/products)\n- api-go     net/http + pgx + postgres    (/orders)\n- web        nginx static + /api/* proxy  (single browser origin)\n\nTooling:\n- docker-compose.yml uses profiles to start subsets (py, node, go, api, web, all)\n- multistack CLI: up/down/logs/status/restart/exec/open\n- Walks up for docker-compose.yml so it works from any subdirectory\n\nCo-Authored-By: Claude Opus 4.7 (1M context) <noreply@anthropic.com>","tree":{"sha":"a33aa0ea4f6d11264790dae2de04f622411eca62","url":"https://api.github.com/repos/MHMALEK/multi-stack-showcase/git/trees/a33aa0ea4f6d11264790dae2de04f622411eca62"},"url":"https://api.github.com/repos/MHMALEK/multi-stack-showcase/git/commits/4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/MHMALEK/multi-stack-showcase/commit/4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f","node_id":"C_kwDOSmnyetoAKDRjODJkOTJkMDlhOWYzZWU1Y2E0YmI2ZTZlMjQxZWJmYjc5MzE0NWY","parents":[],"sha":"4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f","url":"https://api.github.com/repos/MHMALEK/multi-stack-showcase/commits/4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f"}],"requestUrl":"https://api.github.com/repos/MHMALEK/multi-stack-showcase/commits?per_page=100&page=1&sha=4c82d92d09a9f3ee5ca4bb6e6e241ebfb793145f&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A24%3A36.462Z"}');
